24	/**
25	 * Simple JavaBean domain object representing a veterinarian.
26	 *
27	 * @author Ken Krebs
28	 * @author Juergen Hoeller
29	 * @author Sam Brannen
30	 * @author Arjen Poutsma
31	 */
32	@Entity
33	@Table(name = "vets")
34	public class Vet extends Person {
35	
36	    @ManyToMany(fetch = FetchType.EAGER)
37	    @JoinTable(name = "vet_specialties", joinColumns = @JoinColumn(name = "vet_id"),
38	        inverseJoinColumns = @JoinColumn(name = "specialty_id"))
