40	
41	    @JsonIgnore
42	    protected Set<Specialty> getSpecialtiesInternal() {
43	        if (this.specialties == null) {
44	            this.specialties = new HashSet<>();
45	        }
46	        return this.specialties;
47	    }
48	
49	    protected void setSpecialtiesInternal(Set<Specialty> specialties) {
50	        this.specialties = specialties;
51	    }
52	
53	    @XmlElement
54	    public List<Specialty> getSpecialties() {
55	        List<Specialty> sortedSpecs = new ArrayList<>(getSpecialtiesInternal());
56	        sortedSpecs.sort(Comparator.comparing(Specialty::getName, String.CASE_INSENSITIVE_ORDER));
57	        return Collections.unmodifiableList(sortedSpecs);
58	    }
