32	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
33	
34	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
35	        OwnerPageDto ownerPageDto = new OwnerPageDto();
36	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
37	        ownerPageDto.setPage(ownerPage.getNumber());
38	        ownerPageDto.setSize(ownerPage.getSize());
39	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
40	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
41	        return ownerPageDto;
