3	import org.junit.jupiter.api.Test;
4	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
5	import tools.jackson.databind.node.ObjectNode;
6	
7	/** initials: Return 'initials' as the upper-cased first letters of firstName and lastName, dot-separate... */
8	class AcceptanceTest extends AcceptanceBase {
9	
10		@Test
11		void coreComputesInitials() throws Exception {
12			ObjectNode o = ownerNode();
13			o.put("firstName", "john"); o.put("lastName", "smith");
14			int id = createOwnerOk(o);
15			getOwner(id).andExpect(jsonPath("$.initials").value("J.S."));
16		}
17	}
